import fs from "node:fs";
import path from "node:path";

const root = process.cwd();
const payloads = {"src/lib/signal-types.ts": "", "src/lib/signal-engine.ts": "", "src/lib/signal-engine-settings.ts": "", "src/lib/call-story.ts": "", "src/lib/telegram-publisher.ts": ""};

const required = [
  "package.json",
  "src/lib/signal-types.ts",
  "src/lib/signal-engine.ts",
  "src/lib/signal-engine-settings.ts",
  "src/lib/call-story.ts",
  "src/lib/telegram-publisher.ts",
  "src/app/api/telegram/webhook/route.ts",
];

function fail(message) {
  throw new Error(message);
}

for (const relative of required) {
  const full = path.join(root, relative);
  if (!fs.existsSync(full)) {
    fail(`Required file not found: ${relative}`);
  }
}

const checks = [
  ["src/lib/signal-engine.ts", "export function generateSignals("],
  ["src/lib/call-story.ts", "export async function runCallStoryCycle("],
  ["src/lib/telegram-publisher.ts", "export async function publishPendingTelegramSignals()"],
  ["src/app/api/telegram/webhook/route.ts", "function presetTitle("],
  ["src/app/api/telegram/webhook/route.ts", 'command === "/stats"'],
];

for (const [relative, marker] of checks) {
  const text = fs.readFileSync(path.join(root, relative), "utf8");
  if (!text.includes(marker)) {
    fail(`Compatibility marker not found in ${relative}: ${marker}`);
  }
}

const stamp = new Date()
  .toISOString()
  .replace(/[:.]/g, "-");
const backupDir = path.join(
  root,
  ".memescope-backups",
  `public-call-v21-${stamp}`,
);
fs.mkdirSync(backupDir, { recursive: true });

for (const relative of required.slice(1)) {
  const source = path.join(root, relative);
  const target = path.join(backupDir, relative);
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.copyFileSync(source, target);
}

function normalize(text) {
  return text.replace(/\r\n/g, "\n");
}

function replaceRegion(text, startMarker, endMarker, replacement, label) {
  const start = text.indexOf(startMarker);
  if (start < 0) {
    fail(`${label} start marker not found`);
  }
  const end = text.indexOf(endMarker, start + startMarker.length);
  if (end < 0 || end <= start) {
    fail(`${label} end marker not found`);
  }
  return text.slice(0, start) + replacement + text.slice(end);
}

let webhook = normalize(
  fs.readFileSync(
    path.join(root, "src/app/api/telegram/webhook/route.ts"),
    "utf8",
  ),
);

if (!webhook.includes("getCallDashboard")) {
  webhook =
    'import { getCallDashboard } from "@/lib/call-story";\n' +
    webhook;
}

webhook = replaceRegion(
  webhook,
  "function presetTitle(",
  "function presetText(",
  "function presetTitle(\n  preset:\n    | SignalPresetName\n    | \"custom\",\n) {\n  if (\n    preset === \"strict\"\n  ) {\n    return \"SAFE\";\n  }\n\n  if (\n    preset === \"balanced\"\n  ) {\n    return \"BALANCED\";\n  }\n\n  if (\n    preset === \"aggressive\"\n  ) {\n    return \"AGGRESSIVE\";\n  }\n\n  if (\n    preset === \"ultra\"\n  ) {\n    return \"ULTRA\";\n  }\n\n  return \"CUSTOM\";\n}\n\n",
  "presetTitle",
);

webhook = replaceRegion(
  webhook,
  "function presetText(",
  "function presetKeyboard(",
  "function presetText(\n  settings:\n    SignalEngineSettings,\n) {\n  const current =\n    signalPresetName(\n      settings,\n    );\n\n  return [\n    \"<b>MEMESCOPE PRESET CONTROL</b>\",\n    \"\",\n    `Active preset: <b>${presetTitle(\n      current,\n    )}</b>`,\n    \"\",\n    \"<b>Signal sensitivity</b>\",\n    \"\",\n    \"\ud83d\udee1 <b>SAFE</b> - tightest filtering\",\n    \"Score >= 88 | Liq >= $100K | Vol 5m >= $12K | Momentum >= +2.5% | Confirm 2\",\n    \"\",\n    \"\u2696\ufe0f <b>BALANCED</b> - standard mode\",\n    \"Score >= 80 | Liq >= $50K | Vol 5m >= $10K | Momentum >= +2.0% | Confirm 1\",\n    \"\",\n    \"\ud83d\udd25 <b>AGGRESSIVE</b> - earlier and more frequent\",\n    \"Score >= 62 | Liq >= $25K | Vol 5m >= $7K | Momentum >= +1.0% | Confirm 1\",\n    \"\",\n    \"\u26a1 <b>ULTRA</b> - most sensitive early-move preset\",\n    \"Score >= 52 | Liq >= $15K | Vol 5m >= $4K | Momentum >= +0.4% | Confirm 1\",\n    \"\",\n    \"<b>Current values</b>\",\n    `Score >= ${settings.minSignalScore}`,\n    `Liquidity >= ${money(\n      settings.minLiquidityUsd,\n    )}`,\n    `Age = ${settings.minPairAgeMinutes}m - ${settings.maxPairAgeHours}h`,\n    `Volume 5m >= ${money(\n      settings.minVolume5mUsd,\n    )}`,\n    `Transactions 5m >= ${settings.minTransactions5m}`,\n    `Buy pressure = ${(settings.minBuyShare * 100).toFixed(\n      0,\n    )}% - ${(settings.maxBuyShare * 100).toFixed(\n      0,\n    )}%`,\n    `Volume expansion = ${settings.minVolumeSpike.toFixed(\n      2,\n    )}x - ${settings.maxVolumeSpike.toFixed(\n      2,\n    )}x`,\n    `5m momentum = ${settings.minMomentum5m >= 0 ? \"+\" : \"\"}${settings.minMomentum5m.toFixed(\n      1,\n    )}% to +${settings.maxMomentum5m.toFixed(\n      1,\n    )}%`,\n    `Liquidity / valuation >= ${(settings.minLiquidityValuationRatio * 100).toFixed(\n      1,\n    )}%`,\n    `Confirmation = ${settings.confirmationScans} scan${\n      settings.confirmationScans === 1\n        ? \"\"\n        : \"s\"\n    }`,\n    \"\",\n    \"<i>ULTRA relaxes soft gates but still rejects invalid/stale market structures and limited-confidence data.</i>\",\n  ].join(\"\\n\");\n}\n\n",
  "presetText",
);

webhook = replaceRegion(
  webhook,
  "function presetKeyboard(",
  "async function showSettings(",
  "function presetKeyboard(\n  settings:\n    SignalEngineSettings,\n): InlineKeyboard {\n  const current =\n    signalPresetName(\n      settings,\n    );\n\n  const label = (\n    name: SignalPresetName,\n    text: string,\n  ) =>\n    current === name\n      ? `\u2705 ${text}`\n      : text;\n\n  return {\n    inline_keyboard: [\n      [\n        {\n          text:\n            label(\n              \"strict\",\n              \"\ud83d\udee1 Safe\",\n            ),\n          callback_data:\n            \"preset:strict\",\n        },\n        {\n          text:\n            label(\n              \"balanced\",\n              \"\u2696\ufe0f Balanced\",\n            ),\n          callback_data:\n            \"preset:balanced\",\n        },\n      ],\n      [\n        {\n          text:\n            label(\n              \"aggressive\",\n              \"\ud83d\udd25 Aggressive\",\n            ),\n          callback_data:\n            \"preset:aggressive\",\n        },\n        {\n          text:\n            label(\n              \"ultra\",\n              \"\u26a1 Ultra\",\n            ),\n          callback_data:\n            \"preset:ultra\",\n        },\n      ],\n      [\n        {\n          text:\n            \"\ud83d\udd04 Refresh\",\n          callback_data:\n            \"preset:refresh\",\n        },\n      ],\n    ],\n  };\n}\n\n",
  "presetKeyboard",
);

const statsNeedle = 'command === "/stats"';
const statsAt = webhook.indexOf(statsNeedle);
if (statsAt < 0) {
  fail("stats command marker not found");
}
const statsStart = webhook.lastIndexOf("    } else if (", statsAt);
if (statsStart < 0) {
  fail("stats branch start not found");
}
const tokenAt = webhook.indexOf('command === "/token"', statsAt);
if (tokenAt < 0) {
  fail("token command marker after stats not found");
}
const statsEnd = webhook.lastIndexOf("    } else if (", tokenAt);
if (statsEnd <= statsStart) {
  fail("stats branch end not found");
}
webhook =
  webhook.slice(0, statsStart) +
  "    } else if (\n      command === \"/stats\"\n    ) {\n      const dashboard =\n        await getCallDashboard(\n          30,\n        );\n\n      const best =\n        dashboard.topCalls[0] ??\n        null;\n\n      const performanceText = (\n        value:\n          | number\n          | null,\n      ) => {\n        if (\n          value === null ||\n          !Number.isFinite(\n            value,\n          )\n        ) {\n          return \"N/A\";\n        }\n\n        if (value >= 2) {\n          return `${value.toFixed(\n            value >= 10\n              ? 1\n              : 2,\n          )}X`;\n        }\n\n        return `+${Math.max(\n          0,\n          (value - 1) * 100,\n        ).toFixed(0)}%`;\n      };\n\n      const text = [\n        \"<b>MemeScope Calls \u2014 30D</b>\",\n        \"\",\n        `Calls: <b>${dashboard.totalCalls}</b>`,\n        `Running: <b>${dashboard.runningCalls}</b>`,\n        `2X+: <b>${dashboard.reached2x}</b>`,\n        `5X+: <b>${dashboard.reached5x}</b>`,\n        `10X+: <b>${dashboard.reached10x}</b>`,\n        `Best Runner: <b>${\n          best\n            ? `${escapeTelegramHtml(\n                best.symbol,\n              )} ${performanceText(\n                best.peakMultiple,\n              )}`\n            : \"N/A\"\n        }</b>`,\n        `Median Peak: <b>${performanceText(\n          dashboard.medianPeakMultiple,\n        )}</b>`,\n        \"\",\n        \"<i>Based on timestamped MemeScope calls and actual post-call peaks.</i>\",\n      ].join(\"\\n\");\n\n      await reply(\n        chatId,\n        message.message_id,\n        text,\n      );\n" +
  webhook.slice(statsEnd);

if (!webhook.includes("⚡ <b>ULTRA</b>")) {
  fail("Webhook validation failed: ULTRA preset text missing");
}
if (!webhook.includes("getCallDashboard(")) {
  fail("Webhook validation failed: call dashboard stats missing");
}

for (const [relative, encoded] of Object.entries(payloads)) {
  const full = path.join(root, relative);
  fs.mkdirSync(path.dirname(full), { recursive: true });
  fs.writeFileSync(full, Buffer.from(encoded, "base64"));
  console.log(`Updated: ${relative}`);
}

fs.writeFileSync(
  path.join(root, "src/app/api/telegram/webhook/route.ts"),
  webhook,
  "utf8",
);
console.log("Patched: src/app/api/telegram/webhook/route.ts");

fs.rmSync(path.join(root, ".next"), {
  recursive: true,
  force: true,
});

console.log("");
console.log("============================================================");
console.log(" MemeScope Public Call + ULTRA upgrade installed");
console.log("============================================================");
